window.RXP.push(
/* ===== ALERGIA ===== */
{n:'Urticária aguda / reação alérgica leve (criança)',cid:'L50.9 / T78.4',sp:'Alergia pediátrica',ps:[{v:'VO / IM',i:['Checar ANAFILAXIA (pele + respiratório/cardiovascular/GI persistente, ou hipotensão/broncoespasmo/laringe após alérgeno conhecido) → ADRENALINA IM imediata (ver protocolo); urticária isolada (placas pruriginosas fugazes < 24 h cada, sem lesão residual) ± angioedema de pálpebras/lábios sem via aérea = tratar aqui','Causas em crianças: INFECÇÕES VIRAIS (mais comum — 40–60%; pode durar 1–3 semanas com a virose), alimentos (leite, ovo, amendoim, castanhas, trigo, peixe/frutos do mar — início < 2 h), medicamentos (betalactâmicos, AINE, contraste), picadas de inseto, látex, contato (planta, pelos), físicas (frio, calor, pressão, dermografismo); exantema morbiliforme por amoxicilina + virose (EBV) NÃO é urticária/alergia (não suspender necessariamente)','ANTI-H1 DE 2ª GERAÇÃO VO é 1ª linha (igual ao de 1ª geração em eficácia, sem sedação/efeito paradoxal): CETIRIZINA (≥ 6 m) 0,25 mg/kg/dose = {{d;0.25;1;10;mL}} da solução 1 mg/mL (6 m–2 a: 2,5 mg 1–2×/d; 2–5 a: 2,5–5 mg; ≥ 6 a: 10 mg), ou LORATADINA (≥ 2 a) 1 mg/mL: < 30 kg 5 mL / ≥ 30 kg 10 mL 1×/d, ou DESLORATADINA 0,5 mg/mL (6–11 m: 2 mL; 1–5 a: 2,5 mL; 6–11 a: 5 mL), ou fexofenadina/bilastina/rupatadina em maiores; pode DOBRAR–QUADRUPLICAR a dose se não controlar (EAACI — seguro); dose no PS e manter em casa','Anti-H1 de 1ª geração (prometazina IM 0,5 mg/kg; difenidramina; dexclorfeniramina; hidroxizina) — apenas se vômitos/impossibilidade VO ou prurido intenso noturno; prometazina CONTRAINDICADA < 2 anos (depressão respiratória — FDA); sedação, agitação paradoxal','CORTICOIDE sistêmico: NÃO acrescenta benefício na urticária aguda simples (Barniol 2018) — reservar PREDNISOLONA 1 mg/kg (máx. 40) VO por 3–5 d para angioedema importante de face, urticária muito extensa/refratária após dose dobrada de anti-H1, ou doença do soro-like (artralgia + febre + urticária após cefaclor/amoxicilina); evitar corticoide IM de depósito e cursos repetidos','Identificar e SUSPENDER o gatilho (medicamento → registrar alergia e trocar classe; alimento → evitar até avaliação do alergista — não fazer exclusões amplas); evitar AINE/AAS e calor/roupa apertada (agravam); observar 1–2 h se angioedema/reação a alimento ou medicamento (progressão); urticária > 6 semanas = crônica (não é alergia na maioria — alergista: anti-H1 até 4×, omalizumabe ≥ 6–12 a)']}],casa:[{v:'USO ORAL',i:[['Cetirizina solução 1 mg/mL (≥ 6 meses) ou gotas 10 mg/mL (1 gota = 0,5 mg)','1 frasco','Dar {{d;0.25;1;10;mL}} (0,25 mg/kg) 1×/dia (pode dar de 12/12 h se não controlar); 6 m–2 a: 2,5 mL/dia; 2–5 a: 2,5 mL 12/12 h ou 5 mL/dia; ≥ 6 a: 10 mL/dia — por 5–7 dias (ou enquanto durarem as placas) e depois conforme necessidade; se a coceira persistir, pode dobrar a dose por alguns dias'],['OU Loratadina xarope 1 mg/mL (≥ 2 anos)','1 frasco','Dar 5 mL (< 30 kg) ou 10 mL (≥ 30 kg) 1×/dia por 5–7 dias; pode dobrar (12/12 h) se não controlar'],['OU Desloratadina xarope 0,5 mg/mL (≥ 6 meses)','1 frasco','6–11 m: 2 mL; 1–5 a: 2,5 mL; 6–11 a: 5 mL; ≥ 12 a: 10 mL — 1×/dia por 5–7 dias'],['Hidroxizina xarope 2 mg/mL (≥ 6 m) — OPCIONAL, só à noite se prurido impedir o sono','1 frasco','Dar {{d;0.5;2;25;mL}} ao deitar por 2–3 noites (sonolência)'],['Prednisolona solução 3 mg/mL — APENAS se angioedema de face importante ou urticária extensa que não melhorou com anti-H1 em dose dobrada','1 frasco','Dar {{d;1;3;40;mL}} (1 mg/kg, máx. 40 mg) 1×/dia pela manhã por 3–5 dias (sem desmame)']]},{v:'USO TÓPICO (alívio)',i:[['Loção de calamina ou mentol 0,5% em loção / banho morno-frio com aveia coloidal','1 frasco','Aplicar nas placas 3–4×/dia se coceira; compressas frias; evitar banho quente'],['Adrenalina autoinjetor 0,15 mg (< 25–30 kg) / 0,3 mg (≥ 25–30 kg) — SE reação a alimento/inseto com qualquer sintoma além da pele, ou asma + alergia alimentar (orientar e encaminhar)','2 unidades','Aplicar na coxa aos primeiros sinais de reação grave (falta de ar, inchaço de garganta, vômitos repetidos, moleza após alérgeno) e chamar o SAMU 192']]}],ori:['Urticária aguda é AUTOLIMITADA (dias até 1–3 semanas quando por vírus) e as placas MUDAM de lugar (cada uma dura < 24 h) — é esperado "sumir e voltar" em outro local por alguns dias; não é contagiosa; na maioria das crianças NÃO se encontra a causa (vírus) e exames não são necessários','Dar o anti-histamínico TODOS OS DIAS no horário até as placas pararem de surgir por 2–3 dias (não só "quando coçar"); banho morno/frio, roupas leves de algodão, compressas frias; unhas curtas; evitar calor, sol, exercício intenso, roupas apertadas, anti-inflamatórios (ibuprofeno/AAS — pioram urticária), alimentos muito condimentados/corantes durante a crise','Se a causa foi identificada (alimento/medicamento/inseto): evitar e ANOTAR (nome do remédio e data) — levar à consulta; alergia a medicamento deve ser registrada na caderneta; alergia alimentar suspeita → não excluir vários alimentos sem orientação (encaminhar ao alergista para testes; na maioria das vezes a urticária por vírus NÃO é alergia ao que comeu)','Anti-histamínicos "antigos" (dexclorfeniramina — Polaramine®, prometazina — Fenergan®, hidroxizina) dão sono, podem causar agitação e são menos seguros — preferir cetirizina/loratadina/desloratadina; nunca usar prometazina em < 2 anos; pomadas com anti-histamínico/corticoide não ajudam na urticária','Retorno se não melhorar em 7 dias com dose dobrada, se durar > 6 semanas (urticária crônica — investigar e tratar com alergista), ou conforme sinais de alarme'],al:['Inchaço de LÁBIOS/LÍNGUA/GARGANTA, rouquidão, dificuldade para engolir ou respirar, chiado, tosse persistente, vômitos repetidos/dor abdominal forte, palidez/moleza/desmaio/sonolência, principalmente logo após comer algo ou picada → ANAFILAXIA: adrenalina (se tiver) + SAMU 192 imediatamente','Placas que duram > 24 h no MESMO lugar, deixam manchas roxas, com febre, dor nas juntas, inchaço de articulações (vasculite urticariforme/doença do soro/púrpura de Henoch-Schönlein)','Urticária com febre alta persistente e olhos vermelhos/lábios rachados/língua em framboesa (Kawasaki — diferencial), ou bolhas/lesões em alvo/feridas na boca (Stevens-Johnson — após medicamento)','Angioedema recorrente SEM urticária, principalmente com dor abdominal (angioedema hereditário)'],ref:'EAACI/GA²LEN/EuroGuiDerm/APAAACI International Urticaria Guideline 2022 (Zuberbier); ASBAI — Guia Prático de Urticária 2019/2023; SBP — Urticária 2019 (Departamento de Alergia); AAAAI/ACAAI Urticaria Practice Parameter 2014; Barniol Ann Emerg Med 2018 (corticoide sem benefício); Cochrane 2014; Pite Pediatr Allergy Immunol 2013 (urticária aguda em crianças — causas); FDA 2006 (prometazina < 2 a); Fitzsimons 2015 (anti-H1 2ª geração em crianças).'},
{n:'Anafilaxia (criança)',cid:'T78.2 / T78.0',sp:'Alergia pediátrica',ps:[{v:'IM / EV / INALATÓRIO',i:['CRITÉRIOS (WAO 2020): início agudo (min–h) de (1) pele/mucosa (urticária, prurido, flushing, angioedema) + respiratório (dispneia, sibilos, estridor, hipoxemia) OU + cardiovascular (hipotensão, colapso, síncope, incontinência) OU + GI grave (vômitos repetidos, cólica intensa) após alérgeno provável; ou (2) hipotensão/broncoespasmo/laringe após alérgeno CONHECIDO mesmo sem pele; em lactentes: choro inconsolável súbito, hipotonia/"moleza", palidez, vômitos, sonolência podem ser os únicos sinais; hipotensão pediátrica: < 70 + (2 × idade) mmHg (1–10 a); < 70 (< 1 a); < 90 (> 10 a)','ADRENALINA 1 mg/mL (1:1.000) 0,01 mg/kg = {{d;0.01;1;0.5;mL}} IM na FACE ANTEROLATERAL DA COXA (vasto lateral) IMEDIATAMENTE — máx. 0,3 mg (< 12 a) / 0,5 mg (adolescente); repetir a cada 5–15 min se sem melhora (até 3 doses; ~20% precisam de 2ª dose); autoinjetor: 0,15 mg (7,5–25/30 kg) / 0,3 mg (≥ 25–30 kg) / 0,1 mg (< 7,5 kg, se disponível); NÃO há contraindicação; NÃO SC; NÃO EV em bolus (exceto PCR)','POSIÇÃO: deitada com pernas elevadas (sentada se dispneia; lateral se vômitos/inconsciente; gestante adolescente — lateral esquerda); não levantar/andar (morte súbita por "ventrículo vazio"); remover o alérgeno (ferrão — raspar; interromper medicação/transfusão)','O₂ 10–15 L/min em máscara não reinalante (SatO₂ ≥ 94%); acesso venoso/IO (2 se choque); SF 0,9% ou RL {{v;20;1000}} (20 mL/kg) em 5–10 min se hipotensão/má perfusão — repetir até 60 mL/kg; monitorização (ECG, PA, SatO₂)','BRONCOESPASMO persistente após adrenalina: salbutamol spray 100 mcg 4–8 jatos com espaçador (ou NBZ 2,5–5 mg) a cada 20 min; ESTRIDOR/edema de laringe: adrenalina NBZ {{v;0.5;5}} (0,5 mL/kg de 1 mg/mL, máx. 5 mL) além da IM; preparar via aérea difícil (IOT precoce se progressão — cetamina; cricotireoidostomia por punção)','REFRATÁRIA (≥ 3 doses IM + volume): ADRENALINA EV em infusão contínua 0,1–1 mcg/kg/min (0,6 × peso em mg em 100 mL SF → 1 mL/h = 0,1 mcg/kg/min) em bomba, monitorizada — UTI; GLUCAGON 20–30 mcg/kg (máx. 1 mg) EV em 5 min + infusão 5–15 mcg/min se uso de betabloqueador; noradrenalina/vasopressina; ECMO em centros','ADJUVANTES — APÓS a adrenalina, nunca em substituição e não retardam: anti-H1 (difenidramina 1 mg/kg EV/IM máx. 50; ou cetirizina/loratadina VO se tolera) para prurido/urticária; anti-H2 (famotidina 0,25–0,5 mg/kg EV) opcional; CORTICOIDE (metilprednisolona 1–2 mg/kg EV máx. 125; hidrocortisona 4–5 mg/kg máx. 200; ou prednisolona 1–2 mg/kg VO) — NÃO previne reação bifásica de forma comprovada (AAAAI 2020: recomendação CONTRA uso rotineiro para esse fim; opcional em asma/reação prolongada)','OBSERVAÇÃO: mínimo 4–6 h após resolução completa; 12–24 h (internar) se: reação grave (hipotensão/hipoxemia/laringe), > 1 dose de adrenalina, volume EV, história de reação bifásica/anafilaxia grave, asma grave/não controlada, alérgeno de absorção prolongada/desconhecido, distância do PS, lactente; reação bifásica em 5–20% (mediana 8–10 h, até 72 h)','TRIPTASE sérica 30 min–3 h após (comparar com basal 24 h depois — confirma; normal não exclui, sobretudo em alimento); identificar o gatilho (alimentos — leite/ovo/amendoim/castanhas/trigo/peixe/camarão/gergelim — 80% das anafilaxias pediátricas; insetos; medicamentos; látex; cofatores: exercício, febre, AINE); registrar; NOTIFICAR se vacina (ESAVI)']}],casa:[{v:'USO INTRAMUSCULAR — EMERGÊNCIA (carregar sempre; 2 unidades)',i:[['Adrenalina AUTOINJETOR 0,15 mg (EpiPen Jr®/Anapen® 0,15 — 7,5/10 a 25–30 kg) ou 0,3 mg (≥ 25–30 kg) — importado (via alergista/associações); OU, se indisponível: ampola de adrenalina 1 mg/mL + seringa de 1 mL (insulina) com agulha 25×7 ou 30×7, com a dose marcada (validade da ampola; trocar a cada 3–6 meses; proteger da luz) — ensinar a família','2 unidades (uma na mochila/escola, outra em casa)','Aos PRIMEIROS SINAIS de reação grave após contato com o alérgeno (falta de ar, chiado, tosse persistente, rouquidão/"garganta fechando", inchaço de língua/lábios, vômitos repetidos, palidez/moleza/desmaio, urticária extensa com qualquer outro sintoma): aplicar {{d;0.01;1;0.3;mL}} (0,01 mg/kg; máx. 0,3 mL) na face lateral da COXA (pode ser por cima da roupa), segurar 3–10 s; deitar com pernas elevadas; CHAMAR O SAMU 192; repetir em 5–15 min se não melhorar; ir ao PS mesmo que melhore (reação pode voltar)']]},{v:'USO ORAL (após a alta — 3–5 dias)',i:[['Cetirizina solução 1 mg/mL (≥ 6 m) ou Loratadina xarope 1 mg/mL (≥ 2 a)','1 frasco','Cetirizina {{d;0.25;1;10;mL}} de 12/12 h por 3 dias, depois 1×/dia por mais 2–4 dias se prurido/urticária (ou loratadina 5–10 mL 1×/dia)'],['Prednisolona solução 3 mg/mL — opcional (asma associada, reação prolongada; não previne bifásica)','1 frasco','Dar {{d;1;3;40;mL}} (1 mg/kg, máx. 40 mg) 1×/dia pela manhã por 3 dias'],['Salbutamol spray 100 mcg + espaçador — se teve broncoespasmo/asmático','1 frasco','2–4 jatos a cada 4–6 h se chiado/tosse nos próximos 2–3 dias; manter corticoide inalatório de controle']]}],ori:['PLANO DE AÇÃO ESCRITO (entregar e revisar com os pais, escola/creche e cuidadores — modelo ASBAI/FARE): (1) alérgeno e sinais; (2) sintomas LEVES só de pele (coceira/placas sem outro sintoma): anti-histamínico e observar; (3) QUALQUER sinal de gravidade (respiração, garganta, vômitos repetidos, moleza/palidez, ou pele + outro sistema): ADRENALINA PRIMEIRO, deitar, 192, 2ª dose em 5–15 min — "na dúvida, aplique" (adrenalina é segura; o atraso é o que mata); anti-histamínico e corticoide NÃO substituem a adrenalina','EVITAR ESTRITAMENTE o alérgeno: ler TODOS os rótulos ("pode conter"), cuidado com contaminação cruzada (cozinha/escola/festas), informar escola/creche/familiares/restaurantes; alergia a leite/ovo: orientação nutricional (não há "um pouquinho" seguro sem orientação); alergia a inseto: evitar perfumes/cores vivas/comer ao ar livre descalço — IMUNOTERAPIA com veneno é > 95% eficaz (alergista); medicamento: registrar nome/classe, pulseira/cartão de alergia','Carregar SEMPRE 2 doses de adrenalina (mochila, escola, carro, viagens); verificar validade; treinar a família e a escola com o aplicador de demonstração; a lei permite que a escola aplique (orientação por escrito do médico); adolescentes: autoaplicação, álcool e exercício como cofatores, nunca "testar" o alimento','Asma deve estar bem CONTROLADA (é o principal fator de risco de anafilaxia fatal) — corticoide inalatório regular; evitar betabloqueador/IECA se possível (pioram e dificultam o tratamento — discutir com o médico)','ENCAMINHAR ao ALERGISTA/IMUNOLOGISTA pediátrico (urgente — < 4 semanas): confirmação do alérgeno (IgE específica/teste cutâneo/provocação oral), prescrição do autoinjetor, imunoterapia, reavaliação de tolerância (leite/ovo assados), dessensibilização; retorno ao pediatra em 1 semana; vacinas: anafilaxia a ovo NÃO contraindica tríplice viral nem influenza (aplicar em ambiente com suporte); febre amarela: avaliar'],al:['QUALQUER sinal de nova reação nas próximas 72 h (volta da urticária com falta de ar, inchaço de língua/garganta, rouquidão, chiado, vômitos repetidos, moleza/palidez/desmaio, sonolência, dor abdominal intensa) → ADRENALINA IM na coxa + SAMU 192 imediatamente, mesmo que pareça leve ou melhore'],ref:'WAO Anaphylaxis Guidance 2020 (Cardona); EAACI Anaphylaxis Guideline 2021 (Muraro); AAAAI/ACAAI Anaphylaxis Practice Parameter Update 2020 (Shaker — GRADE: corticoide/anti-H1 não previnem bifásica; observação) e 2023; ASBAI — Guia Prático de Anafilaxia 2021/2023 (plano de ação); SBP — Anafilaxia em Pediatria 2021; Resuscitation Council UK 2021; AAP Clinical Report Epinephrine for First-aid Management 2017 (Sicherer); Simons WAO 2011/2015; Cochrane 2010/2012 (adrenalina; corticoide; anti-H1 — sem ECR); Turner JACI 2017 (fatal anaphylaxis — asma); Lee JACI 2015 (bifásica — meta-análise).'},
/* ===== NEUROLOGIA ===== */
{n:'Convulsão febril',cid:'R56.0',sp:'Neurologia pediátrica',ps:[{v:'EV / IM / RETAL / NASAL',i:['DEFINIÇÃO: crise com febre (≥ 38 °C) em 6 MESES–5 ANOS, sem infecção do SNC, sem distúrbio metabólico, sem crise afebril prévia; SIMPLES (70–75%): generalizada, < 15 min, única em 24 h, recuperação completa; COMPLEXA: focal, ≥ 15 min, recorrente em 24 h ou déficit pós-ictal (Todd); estado de mal febril: ≥ 30 min; 2–5% das crianças; recorrência 30% (↑ se < 12–18 m, história familiar, febre baixa/breve antes da crise); risco de epilepsia 1–2% (simples) a 5–10% (complexa) — NÃO causa dano cerebral/déficit intelectual','DURANTE A CRISE (maioria já cessou ao chegar — < 5 min): proteger (lateralizar, nada na boca, afastar objetos), O₂, glicemia capilar, cronometrar; se ≥ 5 min: BENZODIAZEPÍNICO — MIDAZOLAM 0,2 mg/kg IM = {{d;0.2;5;10;mL}} (ampola 5 mg/mL; máx. 10 mg) ou INTRANASAL/BUCAL 0,3 mg/kg (máx. 10 mg; atomizador — tão eficaz quanto diazepam EV e mais rápido sem acesso) OU DIAZEPAM 0,15–0,3 mg/kg EV lento = {{d;0.3;5;10;mL}} (ampola 10 mg/2 mL; máx. 10 mg; 1 mg/min — depressão respiratória) OU diazepam RETAL 0,5 mg/kg (máx. 20 mg; seringa sem agulha, solução injetável — se nada mais disponível); repetir 1× após 5 min; se persistir após 2 doses (≥ 10–20 min): FENITOÍNA 20 mg/kg EV em SF (1 mg/kg/min, máx. 50 mg/min, monitorizado; sem glicose) OU FENOBARBITAL 20 mg/kg EV (lactentes; depressão respiratória) OU LEVETIRACETAM 40–60 mg/kg EV em 5–15 min (máx. 4,5 g; ConSEPT/EcLiPSE: igual à fenitoína, mais seguro) OU ácido valproico 20–40 mg/kg EV; refratária → UTI (midazolam contínuo/tiopental), investigar encefalite/FIRES','APÓS A CRISE — ANTITÉRMICO para conforto (dipirona {{d;15;25;1000;gotas}} VO/EV ou paracetamol {{d;13;13.3;750;gotas}}); antitérmicos NÃO previnem recorrência nem a 1ª crise (Cochrane/AAP) — orientar isso aos pais; IDENTIFICAR A CAUSA DA FEBRE (otoscopia, orofaringe, pele, urina I/urocultura se sem foco, RX se sinais respiratórios, exantema — HHV-6/roséola, influenza, pós-vacinal — tríplice viral 7–14 d, pentavalente 24–48 h)','PUNÇÃO LOMBAR (afastar meningite/encefalite — a febre + crise pode ser a única manifestação): OBRIGATÓRIA se sinais meníngeos/toxemia/rebaixamento persistente > 1 h; FORTEMENTE CONSIDERAR em: < 12 MESES (sinais meníngeos pouco confiáveis), 12–18 meses com dúvida, vacinação incompleta/desconhecida para Hib e pneumococo, uso prévio de antibiótico (mascara meningite), crise complexa/estado de mal febril (sobretudo focal ou com recuperação lenta), > 5 anos; se LCR não puder ser feito e há suspeita: iniciar ceftriaxona 100 mg/kg/dia EV ± aciclovir e internar','EXAMES de rotina (hemograma, eletrólitos, glicemia, cálcio, magnésio): NÃO indicados em crise febril SIMPLES com exame normal (só se vômitos/diarreia/desidratação/suspeita clínica); NEUROIMAGEM (TC/RM): NÃO na simples; na complexa: RM eletiva se focal/déficit/macro-microcefalia/sinais de HIC/trauma; EEG: NÃO na simples (não prediz epilepsia); considerar na complexa/recorrente/focal (ambulatorial, ≥ 1–2 semanas após); crise AFEBRIL/criança > 6 anos ou < 6 meses/atraso do desenvolvimento → não é convulsão febril típica: investigar como 1ª crise afebril','INTERNAR/OBSERVAR: < 12–18 meses (observação 6–12 h e/ou LCR), crise complexa/estado de mal, não retorno ao basal em 1–2 h, sinais de infecção grave/meníngeos, LCR alterado, pais inseguros/distância/sem transporte, 2ª crise nas 24 h; ALTA se: simples, exame neurológico normal após recuperação, foco benigno identificado ou excluída infecção grave, família orientada e com retorno garantido','PROFILAXIA: NÃO indicar anticonvulsivante contínuo (fenobarbital/valproato — efeitos adversos > benefício; AAP 2008) nem intermitente de rotina; DIAZEPAM INTERMITENTE VO 0,33 mg/kg 8/8 h (máx. 10 mg/dose) durante episódios febris (primeiras 48 h) ou clobazam 1 mg/kg/dia — ↓ recorrência (Cochrane 2021: NNT ~10 em 2 anos) mas com sedação/ataxia e sem alterar prognóstico: reservar a casos selecionados (crises prolongadas/múltiplas recorrências/ansiedade familiar extrema, distância do hospital) discutidos com neuropediatra; MIDAZOLAM BUCAL/NASAL (ou diazepam retal) de resgate em casa: orientar para quem já teve crise ≥ 5 min ou complexa']}],casa:[{v:'USO ORAL (conforto — não previne crise)',i:[['Dipirona gotas 500 mg/mL (≥ 3 m) OU Paracetamol gotas 200 mg/mL','1 frasco','Dar {{d;15;25;1000;gotas}} (dipirona) ou {{d;13;13.3;750;gotas}} (paracetamol) de 6/6 h se febre com desconforto; alternar com ibuprofeno {{d;10;5;400;gotas}} (≥ 6 m) de 8/8 h se febre alta persistente — lembrando que o antitérmico serve para o CONFORTO e NÃO evita convulsão'],['Tratamento da CAUSA da febre, se identificada (ex.: amoxicilina para otite — ver protocolo correspondente)','—','Conforme prescrição específica']]},{v:'MEDICAÇÃO DE RESGATE EM CASA (apenas se crise prévia ≥ 5 min, complexa, ou orientação do neuropediatra)',i:[['Midazolam solução oral 2 mg/mL (Dormire®/Dormonid® xarope) ou ampola 5 mg/mL com seringa de 1 mL (uso BUCAL/NASAL) — ≥ 6 meses','1 frasco / 2 ampolas + seringas (manter em local acessível, fora da luz)','Se a crise durar MAIS DE 5 MINUTOS (pelo relógio): aplicar {{d;0.3;5;10;mL}} (0,3 mg/kg da ampola 5 mg/mL; máx. 2 mL = 10 mg) — metade em cada narina (com atomizador) OU entre a bochecha e a gengiva (bucal — não engolir em bolo); se usar o xarope 2 mg/mL: {{d;0.3;2;10;mL}}; deitar de lado; CHAMAR O SAMU 192; NÃO repetir em casa; não dar se já parou'],['OU Diazepam retal 0,5 mg/kg (ampola 10 mg/2 mL com seringa de 3 mL sem agulha, lubrificada; máx. 20 mg)','2 ampolas + seringas','Se crise > 5 min: aplicar {{d;0.5;5;20;mL}} (0,5 mg/kg) no reto, 2–4 cm, segurar as nádegas por 1–2 min; deitar de lado; chamar 192']]}],ori:['A convulsão febril é ASSUSTADORA mas BENIGNA: não causa dano cerebral, não afeta inteligência/desenvolvimento e não é epilepsia; 2–5% das crianças têm; 1 em cada 3 pode repetir (mais se < 1 ano ou parentes que tiveram); o risco de epilepsia no futuro é pouco maior que o de outras crianças (1–2%)','O QUE FAZER se repetir: manter a calma e OLHAR O RELÓGIO; deitar a criança de LADO em local seguro (chão), afastar objetos, afrouxar roupas; NÃO colocar nada na boca (dedo, colher, pano — não há risco de "engolir a língua"), NÃO segurar/sacudir/jogar água, NÃO dar remédio pela boca durante a crise; observar o que acontece (filmar ajuda o médico); a maioria para sozinha em 1–3 min; depois, a criança fica sonolenta/confusa por até 30–60 min (normal) — ficar de lado até acordar; se durar MAIS DE 5 MIN, não acordar após 30 min, repetir no mesmo dia, dificuldade para respirar ou lábios roxos, ou primeira crise com lesão: CHAMAR O SAMU 192 e usar o resgate se tiver','FEBRE: antitérmico serve para o CONFORTO; não previne convulsão (nem dado "preventivo", nem em dose maior, nem alternando) — portanto não precisa acordar a criança para medicar nem ficar aflito com o número; roupas leves, líquidos; banhos frios/álcool NÃO ajudam; não há medicação para "evitar" que valha a pena na maioria dos casos (efeitos colaterais > benefício)','VACINAS: manter o calendário normalmente (a convulsão febril NÃO contraindica vacinas, inclusive tríplice viral/pentavalente) — a febre pós-vacinal pode ser tratada com antitérmico para conforto','Retorno ao pediatra em 1–2 semanas; neuropediatra se crise complexa (focal, > 15 min, repetida em 24 h), atraso do desenvolvimento, exame alterado, crise sem febre, ou muitas recorrências; a maioria NÃO precisa de EEG/tomografia/remédio contínuo'],al:['Crise que dura MAIS DE 5 MINUTOS, repete no mesmo dia/sem acordar entre elas, ou crise de um lado só do corpo → SAMU 192 (resgate se disponível)','Após a crise: não acorda/não responde normalmente em até 30–60 min, muito sonolenta/"mole", vomitando, irritada demais, com dificuldade de andar/falar/mexer um lado','Sinais de MENINGITE: rigidez de nuca/choro ao dobrar o pescoço, moleira abaulada, manchas roxas na pele que não somem com pressão, febre com prostração intensa, vômitos em jato, sonolência, gemência — PS IMEDIATO','Crise SEM febre, em menor de 6 meses ou maior de 5–6 anos, ou em criança com atraso do desenvolvimento (investigar)','Febre sem causa aparente > 48–72 h, dificuldade para respirar, desidratação, qualquer piora'],ref:'AAP Clinical Practice Guideline — Febrile Seizures: Neurodiagnostic Evaluation of the Child with a Simple Febrile Seizure 2011 (Subcommittee) e Long-term Management 2008 (profilaxia); ILAE 2022 (Febrile seizures — definitions); NICE CKS Febrile seizure 2023; SBP — Crise Febril 2021 (Departamento de Neurologia); Liga Brasileira de Epilepsia; Cochrane 2021 (Offringa — prophylactic drug management; antitérmicos não previnem), 2018 (midazolam × diazepam — McTague/Brigo: bucal/nasal eficaz); ConSEPT (Dalziel Lancet 2019) e EcLiPSE (Lyttle Lancet 2019) — levetiracetam × fenitoína; Kimia Pediatrics 2009/2010 (LCR em < 18 m); Guedj Pediatrics 2017 (LCR em crise complexa); Natsume Brain Dev 2017 (JSCN guideline).'},
/* ===== INFECTOLOGIA ===== */
{n:'Dengue (criança)',cid:'A90',sp:'Infectologia pediátrica',ps:[{v:'VO / EV',i:['Em CRIANÇA os sinais podem ser inespecíficos (febre + irritabilidade/prostração/recusa alimentar, vômitos, dor abdominal, exantema; "virose" em área com transmissão = suspeitar) — pode evoluir rápido para choque, mais silenciosamente que adulto; PROVA DO LAÇO (positiva se ≥ 10 petéquias/2,5 cm² em criança — PA média por 3 min); notificação compulsória','CLASSIFICAÇÃO (MS 2024) — GRUPO A: sem alarme, sem sangramento, sem comorbidade/risco, prova do laço negativa → hidratação oral em casa; GRUPO B: prova do laço +, petéquias/sangramento de pele espontâneo, condição especial (< 2 ANOS, gestante adolescente, > 65 a, comorbidades — asma, DM, cardiopatia, DRC, falciforme, obesidade, imunossupressão, autoimune) ou risco social → hemograma no PS + hidratação oral supervisionada até resultado (Ht normal → casa com retorno diário; Ht ↑ ≥ 10% → tratar como C); GRUPO C: ≥ 1 SINAL DE ALARME → INTERNAR: SF 0,9% ou RL {{v;10;}} /h (10 mL/kg/h) EV por 1–2 h, reavaliar (Ht, diurese ≥ 1 mL/kg/h, sinais vitais) → manter 10 mL/kg/h por mais 2 h se melhora ou 20 mL/kg em 20 min se piora → manutenção; GRUPO D: CHOQUE (PA convergente ≤ 20, hipotensão, enchimento capilar > 2 s, extremidades frias, pulso fino, oligúria, letargia) ou sangramento grave/disfunção orgânica → UTI: SF/RL {{v;20;}} (20 mL/kg) em 20 min, repetir até 3× em 1 h; se Ht ↑ persistente → albumina 0,5–1 g/kg ou coloide; Ht ↓ com choque → concentrado de hemácias 10–15 mL/kg; sem resposta → vasoativo; evitar sobrecarga (reavaliar a cada 15–30 min)','SINTOMÁTICOS: DIPIRONA {{d;15;25;1000;gotas}} (≥ 3 m) ou PARACETAMOL {{d;13;13.3;750;gotas}} (máx. 60 mg/kg/dia — hepatotoxicidade; preferir dipirona se transaminases elevadas) de 6/6 h; NUNCA AAS, IBUPROFENO/AINE, corticoide, injeções IM; prurido na recuperação: anti-H1; vômitos: ondansetrona {{d;0.15;0.8;8;mL}} VO (não metoclopramida/dimenidrinato de rotina)','HIDRATAÇÃO ORAL (grupos A/B — MS pediátrico): < 10 kg: 130 mL/kg/dia; 10–20 kg: 100 mL/kg/dia; > 20 kg: 80 mL/kg/dia — 1/3 como SRO e 2/3 com água, água de coco, sucos naturais, chás, sopas, leite materno; oferecer 1/3 do volume nas primeiras 4–6 h (no PS se grupo B); crianças com vômitos: SRO fracionado 5–10 mL a cada 5 min; se não tolerar → EV (grupo C)','EXAMES: Grupo A: não obrigatório (NS1 ≤ 5º dia / IgM ≥ 6º dia se disponível para vigilância); Grupo B: hemograma (Ht, plaquetas) no PS e DIÁRIO até 48 h após a febre; Grupo C/D: hemograma, TGO/TGP, albumina, eletrólitos, gasometria, lactato, coagulograma, creatinina, glicemia, RX tórax/USG abdome (derrame/ascite/vesícula espessada = extravasamento), ECG se miocardite; Ht de referência pediátrico: < 2 a ~36%; 2–10 a ~38%; hemoconcentração = ↑ 10–20%','SINAIS DE ALARME (= grupo C, geralmente na DEFERVESCÊNCIA, 3º–7º dia): dor abdominal intensa e contínua ou à palpação; vômitos persistentes; acúmulo de líquidos (ascite, derrame pleural/pericárdico); sangramento de mucosas; letargia/irritabilidade; hepatomegalia > 2 cm; hipotensão postural/lipotimia; ↑ progressivo do Ht; ↓ brusca de plaquetas; oligúria','ALTA (C/D): afebril 24–48 h, melhora clínica, Ht estável 24 h, plaquetas em ascensão (> 50.000), diurese normal, sem desconforto respiratório/sangramento; retorno ambulatorial em 48 h; VACINA Qdenga® (4–60 a; PNI 10–14 a em áreas prioritárias) — aguardar 6 meses após a infecção']}],casa:[{v:'USO ORAL',i:[['HIDRATAÇÃO ORAL — volume total por dia: {{p;< 10 kg: 130 mL/kg · 10–20 kg: 100 mL/kg · > 20 kg: 80 mL/kg}} = ___ mL/dia (ex.: 15 kg → 1.500 mL/dia), sendo 1/3 de soro de reidratação oral e 2/3 de água/água de coco/suco natural/chá/sopa/leite materno','—','Começar AGORA: oferecer 1/3 do volume total nas primeiras 4–6 h (em copo/colher/seringa, pequenos goles frequentes — a cada 10–15 min); manter o restante ao longo do dia e da noite; continuar por 5–7 dias ou até 48 h após o fim da febre; se vomitar, esperar 10 min e oferecer menos volume mais vezes'],['Sais de reidratação oral (SRO)','6–10 envelopes','Diluir 1 envelope em 1 L de água filtrada/fervida (fria); oferecer 1/3 do volume diário na forma de SRO (ex.: 15 kg → 500 mL/dia); validade 24 h'],['Dipirona gotas 500 mg/mL (≥ 3 meses) — preferencial','1 frasco','Dar {{d;15;25;1000;gotas}} de 6/6 h se febre ou dor (máx. 4×/dia)'],['OU Paracetamol gotas 200 mg/mL (máx. 60 mg/kg/dia — não exceder; fígado é afetado na dengue)','1 frasco','Dar {{d;10;13.3;500;gotas}} (10 mg/kg) de 6/6 h se febre ou dor (máx. 4–5×/dia); pode intercalar com dipirona a cada 3 h'],['Ondansetrona solução 4 mg/5 mL — se vômitos impedirem a hidratação','1 frasco','Dar {{d;0.15;0.8;8;mL}} de 8/8 h só se vomitar, por até 2 dias'],['Loratadina xarope 1 mg/mL (≥ 2 a) ou Cetirizina 1 mg/mL (≥ 6 m) — coceira na fase de recuperação','1 frasco','Loratadina 5 mL (< 30 kg) ou 10 mL 1×/dia; cetirizina {{d;0.25;1;10;mL}} 1×/dia se coceira'],['NÃO DAR: AAS/aspirina, ibuprofeno (Alivium®), diclofenaco, nimesulida, cetoprofeno, naproxeno, corticoide, injeções no músculo — risco de sangramento/choque','—','—']]}],ori:['PERÍODO CRÍTICO: quando a febre BAIXA (3º ao 7º dia) é o momento de maior risco — NÃO é sinal de cura; é quando surgem os sinais de alarme; manter a hidratação e a vigilância mesmo com a criança "melhor"; retorno DIÁRIO (grupo B — levar o cartão de acompanhamento da dengue com hematócrito) ou conforme orientação (grupo A: retorno no 1º dia sem febre ou imediatamente se alarme)','HIDRATAÇÃO é o tratamento: oferecer líquidos com frequência, mesmo sem sede, de dia e de noite (acordar para beber); contar fraldas/xixi (deve urinar pelo menos a cada 4–6 h, urina clara); leite materno à vontade; alimentação leve; repouso; evitar refrigerante/suco industrializado/isotônico de academia como base da hidratação','Remédios: SOMENTE dipirona ou paracetamol para febre/dor; NUNCA aspirina/AAS, ibuprofeno e outros anti-inflamatórios, nem corticoide, nem injeções IM (sangramento); não dar antibiótico (não é bactéria); não usar "remédios caseiros"/chás em excesso (hiponatremia)','Prevenção da transmissão: a criança doente deve ficar sob MOSQUITEIRO/repelente (icaridina ou IR3535 ≥ 6 m; DEET ≥ 2 a — conforme bula) nos primeiros 7 dias (período em que transmite ao mosquito); eliminar criadouros em casa (vasos, pneus, garrafas, calhas, caixa d\'água tampada — 10 min por semana); telas; roupas longas','Vacina (Qdenga®): 10–14 anos nas áreas prioritárias do PNI (2 doses com 3 meses) — após 6 meses da infecção; licença escolar até recuperação (7–10 dias); plaquetas baixas melhoram sozinhas (não precisa de "suco de inhame"/vitamina K — evitar esportes de contato até normalizar)'],al:['SINAIS DE ALARME — voltar IMEDIATAMENTE ao PS (mesmo de madrugada): dor de barriga forte e contínua ou dor ao apertar; vômitos repetidos (≥ 3–4 em 1 h ou 5–6 em 6 h); sangramento de nariz/gengiva/urina/fezes escuras/vômito com sangue/menstruação muito volumosa (adolescente); criança muito sonolenta, "mole", difícil de acordar OU muito irritada/chorosa sem consolo; tontura ao levantar/desmaio; barriga inchada/falta de ar (líquido); mãos e pés frios/pálidos/arroxeados, suor frio; não urina há 6 h ou muito pouca urina; queda brusca da temperatura com piora do estado geral','Febre > 5 dias ou que volta após 2 dias sem febre, convulsão, manchas roxas que aumentam, recusa total de líquidos, confusão/fala estranha','Bebê < 2 anos (sempre grupo B — hemograma e acompanhamento diário) ou criança com asma/diabetes/cardiopatia/anemia falciforme/obesidade/imunossupressão: qualquer piora'],ref:'MS — Dengue: diagnóstico e manejo clínico — adulto e criança, 6ª ed. 2024; MS/SVS — Fluxograma de classificação de risco e manejo 2024 e Nota Técnica (vacina Qdenga 2024); OMS — Guidelines for Clinical Management of Arboviral Diseases 2025 e Dengue Guidelines 2009/2012; OPAS 2022 (Guidelines for the clinical diagnosis and treatment of dengue, chikungunya, and Zika); SBP — Dengue em Pediatria 2024 (Departamento de Infectologia); Cochrane 2014 (corticoide — Zhang/Kularatne: sem benefício) e 2017 (fluidos — coloide × cristaloide); Wills NEJM 2005 (FEAST/dengue fluids); Kalayanarooj; Srikiatkhachorn 2010 (sinais de alarme em crianças).'},
{n:'Conjuntivite (criança) e oftalmia neonatal',cid:'H10.9 / P39.1',sp:'Oftalmologia pediátrica',ps:[{v:'TÓPICO / VO / IM',i:['DIFERENCIAR: BACTERIANA (mais comum em < 5 anos — H. influenzae, S. pneumoniae, M. catarrhalis: secreção PURULENTA abundante que gruda os cílios ao acordar, uni → bilateral, pálpebras edemaciadas; "síndrome otite-conjuntivite" por H. influenzae não tipável → antibiótico VO — amoxicilina-clavulanato); VIRAL (adenovírus — escolares/surtos: aquosa, folículos, linfonodo pré-auricular, IVAS, muito contagiosa; enterovírus/Coxsackie — hemorrágica); ALÉRGICA (prurido intenso bilateral, lacrimejamento, quemose, papilas, atopia/rinite — sazonal); CERATOCONJUNTIVITE VERNAL (meninos 5–12 a, prurido intenso, fotofobia, papilas gigantes "em paralelepípedo", pontos de Trantas — oftalmo); obstrução congênita do ducto nasolacrimal (lactente < 1 a: lacrimejamento + secreção crônica SEM hiperemia conjuntival — massagem de Crigler, antibiótico só se infecção; resolve 90% até 12 m)','SEMPRE: acuidade visual (maiores), reflexo vermelho/pupilas, fluoresceína (ceratite/úlcera/corpo estranho/abrasão), eversão da pálpebra (corpo estranho), fotofobia/dor verdadeira; RED FLAGS para oftalmo: dor ocular intensa, fotofobia importante, baixa visual, opacidade/mancha branca na córnea, pupila irregular, hiperemia ciliar (ao redor da córnea), hipópio, lente de contato, trauma/químico, vesículas (herpes), proptose/dor à movimentação (celulite orbitária), RN','BACTERIANA (criança): colírio antibiótico ENCURTA ~1–2 dias e ↓ transmissão (Cochrane 2023 — benefício modesto; autolimitada em 7–10 d na maioria): TOBRAMICINA 0,3% (1ª escolha — barata, bem tolerada), ciprofloxacino/ofloxacino/moxifloxacino 0,3–0,5%, cloranfenicol 0,5%, azitromicina 1% (2×/d 3 d) — 1 gota 4/4 h (6×/dia) enquanto acordada por 5–7 dias (ou até 48 h após melhora); pomada à noite opcional; LIMPEZA com SF 0,9% gelado/água filtrada e gaze (nunca a mesma gaze nos 2 olhos); NÃO usar corticoide/combinações com corticoide (ceratite herpética, glaucoma, catarata, mascara úlcera) nem vasoconstritores; antibiótico VO só se otite média associada, celulite periorbitária, gonococo/clamídia','VIRAL: lágrima artificial gelada, compressas frias, higiene — sem antibiótico (não previne infecção secundária); duração 1–3 semanas, pior nos dias 3–5, pode "pegar" o outro olho; infiltrados subepiteliais (visão borrada) semanas depois → oftalmo (corticoide só com especialista); afastamento escolar ~7 dias/enquanto lacrimejar','ALÉRGICA: OLOPATADINA 0,1% (≥ 3 a; 12/12 h) ou 0,2% (1×/d) / cetotifeno 0,025% (≥ 3 a) / epinastina — estabilizador + anti-H1 (mais eficaz que anti-H1 oral isolado); lágrima gelada; compressas frias; anti-H1 oral (cetirizina/loratadina) se rinite; evitar coçar (ceratocone); vernal/atópica/grave → oftalmo (ciclosporina/tacrolimo tópicos; corticoide tópico breve só com oftalmo)','OFTALMIA NEONATAL (< 28 dias): GONOCÓCICA (2–5 d de vida; hiperaguda, purulenta copiosa, quemose, risco de perfuração em 24 h — EMERGÊNCIA): internar, CEFTRIAXONA 25–50 mg/kg EV/IM dose única (máx. 125 mg; evitar se hiperbilirrubinemia → cefotaxima 100 mg/kg) + irrigação ocular com SF a cada 1 h + Gram/cultura + investigar sepse/mãe e parceiro; CLAMÍDIA (5–14 d; mucopurulenta, pálpebras edemaciadas, pseudomembrana; pode causar pneumonia afebril 1–3 m): AZITROMICINA VO 20 mg/kg/dia 1×/d por 3 dias (ou eritromicina 50 mg/kg/dia ÷ 4 por 14 d — estenose pilórica) — tópico NÃO basta; tratar mãe/parceiro; QUÍMICA (1º dia — nitrato de prata; autolimitada); HSV (vesículas, ceratite dendrítica — aciclovir EV 60 mg/kg/dia ÷ 3 por 14 d + tópico); outras bacterianas (S. aureus, pneumococo — tópico após Gram); PROFILAXIA ao nascer (nitrato de prata 1% ou povidona-iodo 2,5% ou pomada de eritromicina/tetraciclina) ↓ gonocócica — obrigatória no Brasil','Celulite PRÉ-SEPTAL (pálpebra edemaciada/eritematosa, olho móvel sem dor, sem proptose — pós-sinusite/picada/trauma): amoxicilina-clavulanato {{d;45;80;2000;mL}} VO 12/12 h 7–10 d + reavaliar em 24 h (< 1 ano/toxemia: internar); ORBITÁRIA (proptose, oftalmoplegia dolorosa, quemose, ↓ visão, febre): INTERNAR + TC de órbita/seios + ceftriaxona 100 mg/kg/dia EV ± oxacilina/clindamicina (MRSA) ± drenagem (ORL/oftalmo)']}],casa:[{v:'USO OFTÁLMICO — CONJUNTIVITE BACTERIANA',i:[['Tobramicina 0,3% colírio (Tobrex®/Tobramina®) — qualquer idade','1 frasco','Pingar 1 gota no(s) olho(s) afetado(s) de 4/4 h enquanto acordada (6×/dia) por 5–7 dias (manter até 2 dias após parar a secreção); limpar a secreção com SF/água filtrada e gaze ANTES de pingar; lavar as mãos antes e depois; não encostar o bico no olho/cílios; não usar em casa colírios "da farmácia" com corticoide/vasoconstritor'],['OU Ciprofloxacino 0,3% / Ofloxacino 0,3% / Moxifloxacino 0,5% colírio','1 frasco','Pingar 1 gota de 4/4 h (moxifloxacino: 8/8 h) por 5–7 dias'],['OU Azitromicina 1% colírio (Azyter®) — adesão (poucas doses)','1 frasco','Pingar 1 gota de 12/12 h por 3 dias'],['Tobramicina 0,3% pomada oftálmica — opcional à noite (lactentes/secreção intensa)','1 bisnaga','Aplicar fio de 1 cm no saco conjuntival inferior ao dormir por 5–7 dias']]},{v:'USO OFTÁLMICO — CONJUNTIVITE VIRAL',i:[['Lágrima artificial (carboximetilcelulose 0,5% / hipromelose / hialuronato 0,1–0,15%) sem conservante, mantida na GELADEIRA','1 frasco (ou flaconetes)','Pingar 1–2 gotas em cada olho de 2/2 a 4/4 h enquanto acordada por 7–14 dias (alívio do ardor/areia)'],['Soro fisiológico 0,9% gelado + gaze/algodão','1 frasco','Limpar as secreções 4–6×/dia, do canto interno para o externo, uma gaze para cada olho; compressas frias 10 min 4×/dia']]},{v:'USO OFTÁLMICO — CONJUNTIVITE ALÉRGICA',i:[['Olopatadina 0,1% colírio (Patanol®) (≥ 3 anos) ou Cetotifeno 0,025% (Zaditen®) (≥ 3 anos) ou Epinastina 0,05% (≥ 2 a)','1 frasco','Pingar 1 gota em cada olho de 12/12 h por 2–4 semanas (ou enquanto durar a exposição/estação); olopatadina 0,2% (Patanol S®): 1×/dia'],['Lágrima artificial gelada','1 frasco','1 gota de 4/4 h se coceira/desconforto (lava o alérgeno); compressas frias']]},{v:'USO ORAL (quando indicado)',i:[['Amoxicilina + clavulanato 400/57 mg/5 mL — síndrome otite-conjuntivite (H. influenzae) ou celulite PRÉ-septal leve (≥ 1 ano, sem toxemia)','1–2 frascos','Dar {{d;45;80;2000;mL}} de 12/12 h por 7–10 dias, com alimento'],['Azitromicina 200 mg/5 mL (40 mg/mL) — conjuntivite por CLAMÍDIA no recém-nascido (20 mg/kg/dia por 3 dias) ou síndrome otite-conjuntivite (alergia)','1 frasco','RN com clamídia: {{d;20;40;500;mL}} 1×/dia por 3 dias (tratar mãe e parceiro); criança maior: {{d;10;40;500;mL}} 1×/dia por 5 dias'],['Cetirizina 1 mg/mL (≥ 6 m) ou Loratadina 1 mg/mL (≥ 2 a) — conjuntivite alérgica com rinite','1 frasco','Cetirizina {{d;0.25;1;10;mL}} 1×/dia; loratadina 5–10 mL 1×/dia por 2–4 semanas'],['Dipirona gotas 500 mg/mL (≥ 3 m) / Paracetamol — se dor/febre','1 frasco','{{d;15;25;1000;gotas}} de 6/6 h se necessário']]}],ori:['CONTÁGIO (viral e bacteriana): lavar as mãos com frequência (criança e cuidadores), não coçar/esfregar os olhos, toalha/fronha/lenços individuais (trocar diariamente), não compartilhar colírios, maquiagem, travesseiro; limpar maçanetas/brinquedos; AFASTAR da creche/escola: bacteriana — até 24 h de colírio antibiótico e sem secreção abundante; viral — enquanto houver lacrimejamento/vermelhidão intensa (geralmente 5–7 dias; pode ser mais); alérgica não é contagiosa','LIMPEZA dos olhos: lavar as mãos; soro fisiológico ou água filtrada/fervida fria, gaze ou algodão limpo, do canto do nariz para fora, UMA gaze para cada olho e para cada passada; retirar as crostas ao acordar umedecendo antes; depois pingar o colírio (afastar a pálpebra inferior, 1 gota no "bolsinho", sem tocar); se a criança apertar os olhos, pingar no canto interno com ela deitada e esperar abrir; NÃO usar chás (camomila/erva-doce — infecção/alergia), leite materno (controverso — não substitui tratamento), água boricada caseira, colírios "da farmácia" com corticoide (Maxitrol®, Dexafenicol® etc.) ou vasoconstritor (Colírio Moura Brasil®, Lerin®) — podem causar glaucoma/catarata/ceratite herpética','VIRAL: piora nos primeiros 3–5 dias, pega o outro olho e dura 1–3 semanas — isso é esperado; não há remédio que "cure" (antibiótico não ajuda); o alívio vem do colírio lubrificante gelado e compressas frias; visão levemente embaçada por semanas pode ocorrer (avaliar com oftalmo se persistir); evitar piscina','ALÉRGICA: evitar coçar (piora e pode deformar a córnea — ceratocone), lavar o rosto/olhos com água fria após exposição (poeira, pólen, pelos, piscina), óculos escuros, controle ambiental (capas antiácaro, retirar bichos de pelúcia, evitar fumaça), tratar rinite; usar o colírio antialérgico TODOS os dias durante a estação/exposição, não só quando coça; alergista/oftalmo se persistente/grave','LACTENTE com lacrimejamento + "remela" crônica sem olho vermelho = provável obstrução do canal lacrimal: MASSAGEM de Crigler (pressionar firmemente com o dedo indicador limpo o canto interno do olho, de cima para baixo, 10 vezes, 3–4×/dia), limpar com água filtrada; antibiótico só se infectar (vermelhidão/pus intenso); resolve até 12 meses em 90% — oftalmo se persistir após 12 m ou dacriocistite (inchaço avermelhado doloroso no canto interno)','Retorno em 3–5 dias se não melhorar (viral pode levar até 3 semanas — mas sem piora), ou imediatamente se sinais de alarme'],al:['DOR OCULAR verdadeira (não só ardência/areia), FOTOFOBIA intensa (não consegue abrir o olho na luz), BAIXA DE VISÃO/visão embaçada persistente, mancha branca/opaca na córnea ("parte colorida" com véu), pupila de formato irregular, vermelhidão concentrada ao redor da íris → OFTALMOLOGISTA URGENTE (ceratite/úlcera/uveíte/glaucoma)','Pálpebra MUITO inchada e vermelha com febre, dor ao mover o olho, olho "saltado"/empurrado, visão dupla, criança prostrada → PS imediato (celulite periorbitária/orbitária)','RECÉM-NASCIDO (< 1 mês) com secreção purulenta abundante, pálpebras muito inchadas — EMERGÊNCIA (gonococo pode perfurar o olho em 24 h); secreção em RN de 5–14 dias (clamídia — precisa de antibiótico ORAL)','Bolhinhas/vesículas na pálpebra ou ao redor do olho (herpes), secreção sanguinolenta, trauma/produto químico no olho (lavar com água corrente 15–30 min e ir ao PS), usuária de lente de contato (adolescente) com olho vermelho doloroso','Sem melhora após 5–7 dias de colírio antibiótico ou piora em 48 h; conjuntivite de repetição; otite associada (dor de ouvido/febre — precisa de antibiótico oral)'],ref:'AAO Preferred Practice Pattern — Conjunctivitis 2018/2023; AAP Red Book 2024 (Chlamydia trachomatis; Gonococcal infections — oftalmia neonatal; exclusão escolar); CDC STI Treatment Guidelines 2021 (ophthalmia neonatorum); Cochrane 2023 (Chen — antibiotics for acute bacterial conjunctivitis: benefício modesto, ↓ duração) e 2015 (alérgica — Castillo: estabilizadores/anti-H1 tópicos); SBP — Conjuntivites na Infância 2019 (Departamento de Oftalmologia) e Conjuntivite Neonatal 2021; CBO; Azari JAMA 2013; MS — PCDT IST 2022 (gonococo/clamídia neonatal e profilaxia ocular); Hammerschlag Pediatrics 1998 (azitromicina na clamídia neonatal).'},
{n:'Celulite / adenite cervical / picada de inseto infectada (criança)',cid:'L03.9 / L04.0 / W57',sp:'Dermatologia pediátrica',ps:[{v:'VO / IM / EV',i:['CELULITE (eritema, calor, edema, dor, bordas mal definidas ± febre; porta de entrada: picada, varicela, eczema, ferimento, impetigo; erisipela — bordas nítidas elevadas, estreptococo): delimitar a borda com caneta + hora; dipirona {{d;15;25;1000;gotas}}; ELEVAR o membro; tratar porta de entrada','AMBULATORIAL (criança bem, afebril ou febre baixa, > 6–12 m, área pequena, sem face/periorbitária/mão/articulação/perineal, sem comorbidade, família confiável): CEFALEXINA 50–100 mg/kg/dia ÷ 6/6 h VO 7 dias (1ª dose no PS; {{d;25;50;500;mL}} 6/6 h = 100 mg/kg/dia — infecção mais importante); CELULITE PURULENTA/abscesso/furúnculo/MRSA comunitário suspeito (abscessos recorrentes na família, falha, atleta, pós-drenagem): DRENAR (I&D — é o tratamento do abscesso; antibiótico após drenagem ↑ cura e ↓ recorrência: Talan/Daum) + SMX-TMP 8–12 mg TMP/kg/dia 12/12 h ({{d;5;8;160;mL}}) ou CLINDAMICINA 30 mg/kg/dia ÷ 8/8 h ({{d;10;15;450;mL}} da susp. 75 mg/5 mL) por 7 dias (SMX-TMP não cobre bem estreptococo — associar cefalexina se celulite não purulenta extensa com dúvida)','INTERNAR (EV — OXACILINA 150–200 mg/kg/dia ÷ 6/6 h ou CEFAZOLINA 100 mg/kg/dia ÷ 8/8 h ± CLINDAMICINA/VANCOMICINA se grave/MRSA; CEFTRIAXONA 100 mg/kg/dia se periorbitária/H. influenzae em não vacinado): < 3–6 meses; toxemia/sepse/febre alta; celulite de FACE (sobretudo periorbitária/bucal), mão, períneo, sobre articulação/próxima a osso; extensa (> 5–10% SC) ou rápida progressão (> 2 cm/h); imunossuprimido/diabético/neutropênico; falha oral em 48 h; impossibilidade VO; suspeita de FASCIÍTE NECROSANTE (dor desproporcional, pele tensa/violácea/bolhas hemorrágicas/anestesia/crepitação, toxemia — pós-varicela! → cirurgia urgente + penicilina/oxacilina + clindamicina EV) ou piomiosite/osteomielite/artrite séptica (dor à mobilização, recusa de apoiar — USG/RM)','ADENITE CERVICAL AGUDA BACTERIANA (linfonodo único/unilateral > 2–3 cm, doloroso, quente, eritema cutâneo, febre, 1–4 anos; S. aureus/GAS; após IVAS/faringite/impetigo/dente): CEFALEXINA {{d;25;50;500;mL}} 6/6 h ou AMOXICILINA-CLAVULANATO {{d;45;80;2000;mL}} 12/12 h (anaeróbios/dentária) por 10 dias; USG se flutuação (abscesso → drenagem) ou sem melhora em 48–72 h; internar se < 3 m, toxemia, celulite extensa, comprometimento de via aérea/torcicolo (retrofaríngeo), falha oral; DIFERENCIAIS: adenopatia reativa viral (bilateral, pequena, móvel, indolor — observar 2–4 sem), mononucleose (EBV — faringite + esplenomegalia; amoxicilina → rash), doença da arranhadura do gato (Bartonella — subaguda, contato com gato, azitromicina 10 mg/kg 5 d se sintomática), micobactéria atípica (crônica, violácea, indolor, 1–5 a, fistuliza — cirurgia), tuberculose, KAWASAKI (febre ≥ 5 d + conjuntivite + lábios/língua + exantema + extremidades — IVIG), PFAPA, toxoplasmose, malignidade (supraclavicular, fixo, > 2 cm persistente > 4–6 sem, sintomas B — hemograma/USG/biópsia)','PICADA DE INSETO (mosquito/pulga/percevejo — "estrófulo"/prurigo: pápulas urticadas pruriginosas agrupadas em áreas expostas/linear "café, almoço e jantar"; reação local grande > 10 cm 24–48 h = hipersensibilidade, não infecção): anti-H1 oral (cetirizina {{d;0.25;1;10;mL}} / loratadina / hidroxizina à noite) + corticoide tópico de baixa/média potência (hidrocortisona 1% / mometasona 0,1% fora da face) 2×/dia 5–7 d + compressa fria; INFECTADA (impetiginização por coçar — crosta melicérica/pus/celulite ao redor): limpeza + mupirocina 2% se localizada ou cefalexina VO se celulite/múltiplas; ABELHA/VESPA: raspar o ferrão (não espremer), gelo, anti-H1, analgésico; anafilaxia → adrenalina; ESCORPIÃO/ARANHA em criança: ver protocolo adulto (criança < 7 anos = soro em casos moderados); CARRAPATO: remover com pinça pela base, observar febre/exantema (febre maculosa — doxiciclina em qualquer idade se suspeita); REPELENTES: icaridina 20–25% (≥ 6 m — dura 8–10 h; 1ª escolha no Brasil), IR3535 (≥ 6 m), DEET 10–30% (≥ 2 a — 6–8 h), óleo de eucalipto-limão (≥ 3 a); não em < 6 m (mosquiteiro/roupas)','TÉTANO conforme protocolo se ferimento; RX/USG se corpo estranho/osteomielite; hemograma/PCR/hemocultura apenas se internação; cultura do pus se drenado']}],casa:[{v:'USO ORAL — CELULITE / ADENITE',i:[['Cefalexina suspensão 250 mg/5 mL (50 mg/mL) — 1ª escolha (celulite não purulenta, adenite, picada infectada) — 100 mg/kg/dia','2 frascos (100 mL cada)','Dar {{d;25;50;500;mL}} de 6/6 h por 7 dias (celulite) ou 10 dias (adenite); pode ser dado 8/8 h ({{d;33;50;1000;mL}}) se difícil adesão; guardar na geladeira'],['OU Amoxicilina + clavulanato 400/57 mg/5 mL (80 mg/mL) — adenite de origem dentária/anaeróbios, mordedura, não vacinado Hib','2 frascos','Dar {{d;45;80;2000;mL}} de 12/12 h por 7–10 dias, com alimento'],['OU Sulfametoxazol + trimetoprima 200/40 mg/5 mL (> 2 m) — celulite PURULENTA/abscesso drenado/suspeita de MRSA (associar cefalexina se celulite extensa ao redor)','1 frasco','Dar {{d;5;8;160;mL}} de 12/12 h por 7 dias (10 mg/kg/dia de TMP)'],['OU Clindamicina suspensão 75 mg/5 mL (15 mg/mL) — alergia a betalactâmico / MRSA / abscesso','1–2 frascos','Dar {{d;10;15;450;mL}} de 8/8 h por 7 dias (30 mg/kg/dia); gosto ruim — dar com alimento/suco'],['Dipirona gotas 500 mg/mL (≥ 3 m) ou Ibuprofeno gotas 100 mg/mL (≥ 6 m — dor/edema; evitar se suspeita de varicela/dengue)','1 frasco','Dipirona {{d;15;25;1000;gotas}} de 6/6 h ou ibuprofeno {{d;10;5;400;gotas}} de 8/8 h se dor/febre']]},{v:'USO ORAL / TÓPICO — PICADAS DE INSETO (não infectadas)',i:[['Cetirizina solução 1 mg/mL (≥ 6 m) ou Loratadina 1 mg/mL (≥ 2 a) — coceira (dia)','1 frasco','Cetirizina {{d;0.25;1;10;mL}} 1×/dia (ou 12/12 h se intensa); loratadina 5–10 mL 1×/dia — por 5–7 dias'],['Hidroxizina xarope 2 mg/mL (≥ 6 m) — coceira intensa à noite','1 frasco','Dar {{d;0.5;2;25;mL}} ao deitar por 3–5 noites'],['Hidrocortisona 1% creme (face/dobras/< 2 a) ou Mometasona 0,1% creme (tronco/membros, ≥ 2 a)','1 bisnaga','Aplicar fina camada nas picadas 2×/dia (mometasona 1×/dia) por 5–7 dias; compressa fria 10 min antes alivia'],['Mupirocina 2% pomada — picadas com crosta amarelada/pus localizadas (coçadas e infectadas)','1 bisnaga','Aplicar nas lesões 3×/dia por 5–7 dias após limpar com água e sabão'],['Repelente: Icaridina 20–25% (Exposis®/Repelex Kids® — ≥ 6 meses) ou IR3535 (≥ 6 m) ou DEET 10–30% (≥ 2 anos)','1 frasco','Aplicar nas áreas expostas (não em mãos/olhos/boca/pele lesada; o adulto aplica) 1–3×/dia conforme a duração do produto (icaridina 25%: até 10 h); reaplicar após banho/suor; protetor solar antes, repelente depois; < 6 meses: só mosquiteiro, telas e roupas']]}],ori:['CELULITE: ELEVAR a perna/braço acima do nível do coração o máximo possível (deitado com travesseiro sob o membro) — reduz dor/inchaço e acelera a cura; marcar a borda da vermelhidão com caneta para comparar; a vermelhidão pode avançar um pouco nas primeiras 24–48 h mesmo com antibiótico certo, mas a FEBRE e a DOR devem melhorar em 48–72 h; RETORNO OBRIGATÓRIO em 48 h; dar o antibiótico de 6/6 h (4×/dia, com seringa) até o fim; compressas mornas 15 min 3–4×/dia (adenite/abscesso em formação); não espremer/furar; curativo limpo se ferida aberta','ADENITE ("íngua"): comum após infecção de garganta/ouvido/dente/pele; melhora em 2–3 dias de antibiótico; o gânglio pode demorar semanas para diminuir totalmente (normal); se amolecer/flutuar (pus) → precisa drenar (voltar); cuidar dos dentes (cárie como causa); gânglios pequenos (< 1 cm), móveis, indolores em várias regiões após virose são normais e somem em 2–4 semanas sem remédio','PICADAS: lavar com água e sabão; NÃO COÇAR (unhas curtas; luvas/meias nas mãos do bebê à noite) — coçar infecta e deixa manchas/cicatrizes; compressa fria/gelo com pano 10 min; anti-histamínico e corticoide tópico conforme receita; pomadas "de picada" com anti-histamínico/anestésico/benzocaína (Andantol®, Polaramine creme®, Caladryl® com difenidramina) NÃO são recomendadas em crianças (sensibilização/toxicidade); a reação local grande (> 10 cm, inchaço por 2–3 dias) é "alergia local", não infecção — não precisa de antibiótico se sem pus/febre/dor crescente','PREVENÇÃO: mosquiteiro (berço/cama/carrinho), telas, roupas claras compridas ao entardecer, repelente adequado à idade (icaridina ≥ 6 m; DEET ≥ 2 a; óleos "naturais"/citronela têm proteção curta — não confiar em áreas de dengue/malária), eliminar criadouros/água parada, tratar animais domésticos contra pulgas/carrapatos, evitar perfumes doces; pulgas/percevejos: dedetizar/lavar roupas de cama a quente','Porta de entrada: hidratar a pele (eczema), tratar micose entre os dedos, impetigo e sarna; vacinas em dia (varicela — celulite/fasciíte pós-varicela)'],al:['Vermelhidão que se espalha RAPIDAMENTE (horas), estrias vermelhas subindo pelo membro, inchaço muito tenso/pele brilhante, bolhas/manchas roxas ou escuras, dor MUITO forte ou, ao contrário, dormência no local (fasciíte necrosante — EMERGÊNCIA cirúrgica), crepitação','Febre alta persistente após 48–72 h de antibiótico, prostração, vômitos (não consegue tomar o remédio), calafrios, confusão, pouca urina (sepse)','Celulite no ROSTO (principalmente ao redor do olho — olho inchado/fechado, dor para mexer, visão dupla), na mão (dedo que não dobra/dor ao esticar), sobre articulação (joelho/cotovelo quente, não apoia a perna/não mexe o braço — artrite séptica/osteomielite), na região genital/anal, em bebê < 3 meses','Gânglio no pescoço que cresce rápido, endurece, > 3–4 cm, flutua (pus), com dificuldade de engolir/respirar/virar o pescoço (abscesso profundo), ou que persiste > 4–6 semanas, acima da clavícula, com perda de peso/suores noturnos/palidez (investigar); febre ≥ 5 dias com olhos vermelhos, lábios rachados, língua framboesa, mãos/pés inchados (Kawasaki)','Picada com reação geral: urticária pelo corpo, inchaço de lábios/olhos, chiado/falta de ar, vômitos, moleza (ANAFILAXIA — SAMU 192); febre + exantema/manchas após carrapato; dor intensa/suor/vômitos após picada de escorpião/aranha (soro)'],ref:'IDSA SSTI Guideline 2014 (Stevens); AAP Red Book 2024 (S. aureus/MRSA; GAS; Bartonella; exclusion); SBP — Infecções de Pele e Partes Moles 2020 (Departamento de Infectologia/Dermatologia) e Linfadenopatias 2019; Talan NEJM 2016 e Daum NEJM 2017 (antibiótico após drenagem de abscesso — SMX-TMP/clindamicina); Cochrane 2010 (celulite/erisipela — Kilburn) e 2018 (abscesso — Vermandere); Moran NEJM 2017 (cefalexina ± SMX-TMP em celulite não purulenta); Gosche Pediatr Rev 2006 (adenite); Weinberger/Newburger AHA Kawasaki 2017; AAP Clinical Report Insect Repellents (Pediatrics 2013/2020; EPA); SBD — Prurigo estrófulo 2019; MS — Guia de Vigilância 2024 (febre maculosa; peçonhentos).'}
);
